// O(n): may check every item
bool inList(List<String> ids, String id) => ids.contains(id);
// O(1) on average: hash lookup
bool inSet(Set<String> ids, String id) => ids.contains(id);
void main() {
  final ids = List.generate(100000, (i) => '$i');
  print(inList(ids, '99999'));
  print(inSet(ids.toSet(), '99999'));
}

class Category {
  Category(this.name, [this.children = const []]);
  final String name;
  final List<Category> children;
}
// base case: a category with no children returns 1
int countAll(Category c) =>
    1 + c.children.fold<int>(0, (sum, child) => sum + countAll(child));
void main() {
  final root = Category('کالای دیجیتال', [Category('موبایل', [Category('گوشی')])]);
  print(countAll(root)); // 3
}

