import 'dart:isolate';

int sumTo(int n) {
  var sum = 0;
  for (var i = 1; i <= n; i++) {
    sum += i;
  }
  return sum;
}

Future<void> main() async {
  final result = await Isolate.run(() => sumTo(100000000));
  print(result);
}

