class CityRepository {
  final _cache = <String, List<String>>{};

  Future<List<String>> cities(String province) async {
    final cached = _cache[province];
    if (cached != null) return cached; // cache hit
    await Future.delayed(const Duration(seconds: 1)); // fake network call
    return _cache[province] = ['تهران', 'ری'];
  }
}

class Cart {
  const Cart({this.items = const []});
  final List<String> items;
  Cart copyWith({List<String>? items}) => Cart(items: items ?? this.items);
}

void main() {
  const empty = Cart();
  final updated = empty.copyWith(items: [...empty.items, 'پیتزا']);
  print('${empty.items.length} ${updated.items.length}'); // 0 1
}

abstract class TransferRepository {
  Future<void> transfer(String toCard, int toman);
}
class TransferMoney {
  TransferMoney(this.repo);
  final TransferRepository repo;
  static const dailyLimit = 50000000;
  Future<void> call(String toCard, int toman) {
    if (toman > dailyLimit) throw ArgumentError('بیش از سقف روزانه');
    return repo.transfer(toCard, toman);
  }
}
